package com.guocheng.mediapocket;
import android.os.*;import android.text.Editable;import android.text.TextWatcher;import android.view.*;import android.widget.*;import org.json.*;
/** 挂到现有搜索页的输入框上，同时查已添加的 Emby 服务器。 */
final class EmbySearch {
 static void attach(ScrapedMainActivity a){JSONArray servers=EmbyStore.list(a);if(servers.length()==0||a.body==null)return;LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setTag("emby-search");a.body.addView(box,0);TextView note=a.text("Emby · "+servers.length()+" 个服务器，输入片名后一起搜索",12,a.muted());box.addView(note);LinearLayout results=new LinearLayout(a);results.setOrientation(1);box.addView(results);EditText input=find(a.getWindow().getDecorView());if(input==null)return;Handler handler=new Handler(Looper.getMainLooper());final int[] generation={0};
  input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int n){}public void onTextChanged(CharSequence s,int st,int b,int c){}public void afterTextChanged(Editable s){int token=++generation[0];String word=s.toString().trim();handler.removeCallbacksAndMessages(null);if(word.length()<2){results.removeAllViews();return;}handler.postDelayed(()->{if(token!=generation[0]||a.isFinishing())return;results.removeAllViews();results.addView(a.text("正在搜索 Emby…",12,a.muted()));EmbyPlayback.IO.execute(()->{JSONArray found=new JSONArray();String failure="";try{for(int i=0;i<servers.length();i++){JSONObject server=servers.optJSONObject(i);if(server==null)continue;JSONArray items=EmbyClient.search(a,server,word).optJSONArray("Items");if(items==null)continue;for(int n=0;n<items.length()&&found.length()<24;n++){JSONObject m=EmbyApi.meta(server,items.optJSONObject(n));m.put("name",m.optString("name")+" · "+server.optString("name","Emby"));found.put(m);}}}catch(Exception e){failure=EmbyApi.explain(e);}String reason=failure;a.runOnUiThread(()->{if(token!=generation[0]||a.isFinishing())return;results.removeAllViews();if(found.length()==0){results.addView(a.text(reason.isEmpty()?"Emby 没有匹配的影片":reason,12,a.muted()));return;}a.shelf(results,found,"movie",false);});});},350);}});
 }
 static EditText find(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=find(g.getChildAt(i));if(e!=null)return e;}}return null;}
 private EmbySearch(){}
}
